//! Real-transaction fixtures: Solana RPC `getTransaction` JSON (maxSupportedTransactionVersion=1)
//! decoded by the package's decoder, compared with expectations generated by an independent
//! IDL-driven decoder (`verify/idldec.py`). Run `cargo test`.
use std::collections::{BTreeMap, HashMap};
use std::fs;

use jupiter_lend_substreams::decoder::decode_tx;
use jupiter_lend_substreams::pb::jupiter_lend::v1::*;
use jupiter_lend_substreams::tx::{Ix, TxInput};
use serde_json::Value;

fn tx_from_rpc(v: &Value) -> TxInput {
    let msg = &v["transaction"]["message"];
    let meta = &v["meta"];
    let mut keys: Vec<String> =
        msg["accountKeys"].as_array().unwrap().iter().map(|k| k.as_str().unwrap().to_string()).collect();
    for k in ["writable", "readonly"] {
        if let Some(a) = meta["loadedAddresses"][k].as_array() {
            keys.extend(a.iter().map(|x| x.as_str().unwrap().to_string()));
        }
    }
    let mk = |ix: &Value, h: u32| Ix {
        program_id: keys[ix["programIdIndex"].as_u64().unwrap() as usize].clone(),
        data: bs58::decode(ix["data"].as_str().unwrap()).into_vec().unwrap(),
        accounts: ix["accounts"].as_array().unwrap().iter().map(|a| keys[a.as_u64().unwrap() as usize].clone()).collect(),
        stack_height: ix["stackHeight"].as_u64().map(|x| x as u32).unwrap_or(h),
    };
    let mut inner: HashMap<u64, &Vec<Value>> = HashMap::new();
    if let Some(a) = meta["innerInstructions"].as_array() {
        for g in a {
            inner.insert(g["index"].as_u64().unwrap(), g["instructions"].as_array().unwrap());
        }
    }
    let mut walk = Vec::new();
    for (i, ix) in msg["instructions"].as_array().unwrap().iter().enumerate() {
        walk.push(mk(ix, 1));
        if let Some(list) = inner.get(&(i as u64)) {
            for x in list.iter() {
                walk.push(mk(x, 2));
            }
        }
    }
    let mut mints = HashMap::new();
    for k in ["preTokenBalances", "postTokenBalances"] {
        if let Some(a) = meta[k].as_array() {
            for b in a {
                mints.entry(b["mint"].as_str().unwrap().to_string()).or_insert((
                    b["uiTokenAmount"]["decimals"].as_u64().unwrap() as u32,
                    b["programId"].as_str().unwrap_or("").to_string(),
                ));
            }
        }
    }
    TxInput {
        slot: v["slot"].as_u64().unwrap(),
        block_time: v["blockTime"].as_i64().unwrap_or(0),
        tx_id: v["transaction"]["signatures"][0].as_str().unwrap().to_string(),
        tx_index: 0,
        fee_payer: keys[0].clone(),
        walk,
        logs: meta["logMessages"].as_array().unwrap().iter().map(|l| l.as_str().unwrap().to_string()).collect(),
        mints,
    }
}

type Flat = BTreeMap<(String, u32), BTreeMap<String, String>>;

macro_rules! flat {
    ($out:expr, $list:expr, $name:literal, [$($f:ident => $k:literal),* $(,)?]) => {
        for e in $list.iter() {
            let c = e.ctx.as_option().unwrap();
            let mut m = BTreeMap::new();
            m.insert("instruction".to_string(), c.instruction.clone());
            $( m.insert($k.to_string(), e.$f.to_string()); )*
            $out.insert(($name.to_string(), c.log_index), m);
        }
    };
}

fn flatten(ev: &Events) -> Flat {
    let mut o = Flat::new();
    flat!(o, ev.liquidity_operates, "liquidityOperates", [protocol => "protocol", protocol_type => "protocolType", mint => "mint",
        supply_amount_raw => "supplyAmountRaw", borrow_amount_raw => "borrowAmountRaw", withdraw_to => "withdrawTo", borrow_to => "borrowTo",
        supply_exchange_price => "supplyExchangePrice", borrow_exchange_price => "borrowExchangePrice", decimals => "decimals"]);
    flat!(o, ev.liquidity_exchange_prices, "liquidityExchangePrices", [mint => "mint", supply_exchange_price => "supplyExchangePrice",
        borrow_exchange_price => "borrowExchangePrice", borrow_rate_bps => "borrowRateBps", utilization_bps => "utilizationBps"]);
    flat!(o, ev.earn_deposits, "earnDeposits", [sender => "sender", receiver => "receiver", assets_raw => "assetsRaw",
        shares_minted_raw => "sharesMintedRaw", mint => "mint", f_token_mint => "fTokenMint", lending => "lending"]);
    flat!(o, ev.earn_withdraws, "earnWithdraws", [sender => "sender", receiver => "receiver", owner => "owner", assets_raw => "assetsRaw",
        shares_burned_raw => "sharesBurnedRaw", mint => "mint", f_token_mint => "fTokenMint", lending => "lending"]);
    flat!(o, ev.earn_update_rates, "earnUpdateRates", [mint => "mint", f_token_mint => "fTokenMint", lending => "lending",
        token_exchange_price => "tokenExchangePrice", liquidity_exchange_price => "liquidityExchangePrice"]);
    flat!(o, ev.vault_operates, "vaultOperates", [vault_id => "vaultId", vault_config => "vaultConfig", supply_mint => "supplyMint",
        borrow_mint => "borrowMint", nft_id => "nftId", signer => "signer", to => "to", col_change_raw => "colChangeRaw",
        debt_change_raw => "debtChangeRaw", vault_type => "vaultType"]);
    flat!(o, ev.vault_user_positions, "vaultUserPositions", [user => "user", nft_id => "nftId", vault_id => "vaultId",
        position_mint => "positionMint", tick => "tick", col_raw => "colRaw", borrow_raw => "borrowRaw", vault_config => "vaultConfig"]);
    flat!(o, ev.vault_liquidates, "vaultLiquidates", [vault_id => "vaultId", vault_config => "vaultConfig", signer => "signer", to => "to",
        col_amount_raw => "colAmountRaw", debt_amount_raw => "debtAmountRaw", vault_type => "vaultType"]);
    flat!(o, ev.vault_absorbs, "vaultAbsorbs", [col_amount_raw => "colAmountRaw", debt_amount_raw => "debtAmountRaw"]);
    flat!(o, ev.dex_swaps, "dexSwaps", [dex_id => "dexId", swap0_to1 => "swap0To1", maker => "maker", to => "to", amount_in_raw => "amountInRaw",
        amount_out_raw => "amountOutRaw", fee_amount_in_raw => "feeAmountInRaw", reserves_token0 => "reservesToken0",
        reserves_token1 => "reservesToken1", pool_price => "poolPrice", dex => "dex", token0 => "token0", token1 => "token1"]);
    flat!(o, ev.dex_liquidity, "dexLiquidity", [dex_id => "dexId", shares_raw => "sharesRaw", token0_amount_raw => "token0AmountRaw",
        token1_amount_raw => "token1AmountRaw", user => "user", protocol => "protocol"]);
    flat!(o, ev.rewards_starts, "rewardsStarts", [mint => "mint", reward_amount_raw => "rewardAmountRaw", duration => "duration", start_time => "startTime"]);
    flat!(o, ev.rewards_stops, "rewardsStops", [mint => "mint"]);
    o
}

#[test]
fn real_transactions_match_independent_idl_decode() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");
    let mut files: Vec<_> = fs::read_dir(dir).unwrap().filter_map(|e| e.ok()).map(|e| e.path()).collect();
    files.sort();
    let (mut txs, mut events, mut fields) = (0, 0, 0);
    for p in files.iter().filter(|p| p.to_string_lossy().ends_with(".tx.json")) {
        let tx: Value = serde_json::from_str(&fs::read_to_string(p).unwrap()).unwrap();
        let exp_path = p.to_string_lossy().replace(".tx.json", ".expected.json");
        let exp: Value = serde_json::from_str(&fs::read_to_string(&exp_path).unwrap()).unwrap();
        let input = tx_from_rpc(&tx);
        let mut ev = Events::default();
        assert!(decode_tx(&input, &mut ev), "{}: incomplete logs", p.display());
        let got = flatten(&ev);
        let exp_list = exp.as_array().unwrap();
        assert_eq!(got.len(), exp_list.len(), "{}: event count", p.display());
        for e in exp_list {
            let key = (e["list"].as_str().unwrap().to_string(), e["log_index"].as_u64().unwrap() as u32);
            let g = got.get(&key).unwrap_or_else(|| panic!("{}: missing {:?}", p.display(), key));
            for (k, v) in e["fields"].as_object().unwrap() {
                let want = match v {
                    Value::String(s) => s.clone(),
                    other => other.to_string(),
                };
                assert_eq!(g.get(k).map(|s| s.as_str()), Some(want.as_str()), "{}: {:?}.{}", p.display(), key, k);
                fields += 1;
            }
            events += 1;
        }
        txs += 1;
    }
    assert!(txs >= 10, "expected fixtures");
    eprintln!("fixtures: {} txs, {} events, {} fields matched", txs, events, fields);
}
